import math

def f(x):
    return math.sqrt(3*x + 1) - math.sqrt(x - 1) - 2

roots = []
step = 0.01
N = 200000
prev_x = 1.0
prev = f(prev_x)
if abs(prev) < 1e-12:
    roots.append(prev_x)
for i in range(1, N + 1):
    x = 1.0 + i * step
    cur = f(x)
    if abs(cur) < 1e-12:
        roots.append(x)
    elif prev * cur < 0:
        lo, hi = prev_x, x
        for _ in range(100):
            mid = (lo + hi) / 2
            if f(lo) * f(mid) <= 0:
                hi = mid
            else:
                lo = mid
        roots.append((lo + hi) / 2)
    prev_x, prev = x, cur
uniq = []
for r in roots:
    if not uniq or abs(r - uniq[-1]) > 1e-6:
        uniq.append(r)
print(int(round(sum(uniq))))

